@push('scripts')
<script>
function bookCarousel() {
  return {
    timer: null,
    speed: 0.8,
    isDragging: false,
    startX: 0,
    scrollLeftStart: 0,
    wheelTimer: null,
    init() {
      this.resume();
      this.setupDrag();
    },
    step() {
      if (this.isDragging) return;
      const track = this.$refs.track;
      track.scrollLeft += this.speed;
      if (track.scrollLeft >= track.scrollWidth / 3) {
        track.scrollLeft = 0;
      }
    },
    pause() {
      if (this.timer) {
        clearInterval(this.timer);
        this.timer = null;
      }
    },
    resume() {
      if (!this.timer) {
        this.timer = setInterval(() => this.step(), 30);
      }
    },
    setupDrag() {
      const track = this.$refs.track;
      let hasMoved = false;

      const onMouseDown = (e) => {
        this.isDragging = true;
        hasMoved = false;
        this.startX = e.pageX - track.offsetLeft;
        this.scrollLeftStart = track.scrollLeft;
      };
      const onMouseMove = (e) => {
        if (!this.isDragging) return;
        const x = e.pageX - track.offsetLeft;
        const distance = Math.abs(x - this.startX);
        if (distance > 5) {
          hasMoved = true;
          track.classList.add('is-dragging');
          e.preventDefault();
          const walk = (x - this.startX) * 2;
          track.scrollLeft = this.scrollLeftStart - walk;
        }
      };
      const onMouseUp = (e) => {
        if (this.isDragging) {
          if (hasMoved) { e.preventDefault(); }
          this.isDragging = false;
          hasMoved = false;
          track.classList.remove('is-dragging');
        }
      };

      track.addEventListener('mousedown', onMouseDown);
      document.addEventListener('mousemove', onMouseMove);
      document.addEventListener('mouseup', onMouseUp);
      track.addEventListener('mouseleave', onMouseUp);
      track.addEventListener('click', (e) => {
        if (hasMoved) { e.preventDefault(); e.stopPropagation(); }
      }, true);
    },
    scrollWheel(event) {
      this.$refs.track.scrollLeft += event.deltaY || event.deltaX;
      clearTimeout(this.wheelTimer);
      this.wheelTimer = setTimeout(() => {}, 1000);
    }
  };
}
</script>
